  bp: number | null;
  deltaBp: number | null;
  source: MarketSource | null;
  /** Уровень наличия со страницы сборщика или из процента (DATA_MODEL §23.1); у старых ответов поля нет */
  level?: 'SOLD_OUT' | 'FEW_LEFT' | 'AVAILABLE' | null;
